    """Return a version string with the specified components replaced.

    Accepts the component names ``major``, ``minor``, ``patch``,
    ``prerelease``, and ``build``. Unspecified components are preserved.

    >>> replace('1.2.3-rc.1+build.4', minor=5, prerelease=None)
    '1.5.3+build.4'
    """
    return str(parse_version_info(version).replace(**parts))


